import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"发布流程（SOP）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/process.md","filePath":"zh/release/process.md"}'),o={name:"zh/release/process.md"};function d(l,e,n,c,p,r){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="发布流程-sop" tabindex="-1">发布流程（SOP） <a class="header-anchor" href="#发布流程-sop" aria-label="Permalink to &quot;发布流程（SOP）&quot;">​</a></h1><p>发布走过的确切序列。每一步都有门；门失败即停。</p><h2 id="_0-预检" tabindex="-1">0. 预检 <a class="header-anchor" href="#_0-预检" aria-label="Permalink to &quot;0. 预检&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git fetch &amp;&amp; git status        （干净树、正确分支）</span></span>
<span class="line"><span>git tag --list &#39;v*&#39;            （新 tag 尚不存在）</span></span>
<span class="line"><span>git config user.name / user.email   （作者 = cubestudio-dev &lt;cubestudio@qq.com&gt;）</span></span></code></pre></div><h2 id="_1-构建" tabindex="-1">1. 构建 <a class="header-anchor" href="#_1-构建" aria-label="Permalink to &quot;1. 构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make clean &amp;&amp; make -j$(nproc) all</span></span></code></pre></div><p>门：0 错误 0 警告（<code>-Wall -Wextra -Werror</code> 在编译参数里） <strong>且本地工具链与 GitHub Actions runner 双双通过</strong>——2.0.0 发布过 本地能编译、CI 编不过的源码（tui_core.c 端口约束 P0；见 KNOWN_ISSUES.md）。CI 绿是硬性发布门，不是锦上添花。 产出：<code>build/opencube.iso</code>、<code>dist/OpenCubeOS-&lt;ver&gt;-src.zip</code>、 <code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code>。</p><h2 id="_2-可复现" tabindex="-1">2. 可复现 <a class="header-anchor" href="#_2-可复现" aria-label="Permalink to &quot;2. 可复现&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make reproducible-check</span></span></code></pre></div><p>门：<code>PASS - ELF byte-identical across two clean builds</code>。</p><h2 id="_3-启动门" tabindex="-1">3. 启动门 <a class="header-anchor" href="#_3-启动门" aria-label="Permalink to &quot;3. 启动门&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios      （横幅 + Ring-3 ush&gt; + boot complete）</span></span>
<span class="line"><span>make run-uefi      （同上，走 OVMF）</span></span></code></pre></div><p>默认启动落在 Ring-3 的 <code>ush&gt;</code>；<code>exit</code> 之后（或启动器失败时）出现 <code>oc&gt;</code>——恢复姿态。</p><h2 id="_4-深度测试门-在构建出的-iso-上" tabindex="-1">4. 深度测试门（在构建出的 ISO 上） <a class="header-anchor" href="#_4-深度测试门-在构建出的-iso-上" aria-label="Permalink to &quot;4. 深度测试门（在构建出的 ISO 上）&quot;">​</a></h2><p>2.1.0 验证矩阵——每套都驱动真实 QEMU 启动、走串口控制台；把真实 输出（含 skip 数）贴进发布证据：</p><table tabindex="0"><thead><tr><th>门</th><th>命令</th><th>证明什么</th></tr></thead><tbody><tr><td>Host 单测</td><td><code>make test</code></td><td>17 项 PASS（无 openssl fixture 时 +2 SKIP-FIXTURE——如实申报 skip）</td></tr><tr><td>看门狗/日志/健康 E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>14 场景（S1-S14，含 Intel TCO 真复位）</td></tr><tr><td>TUI 命令面 E2E</td><td><code>tools/wp10_tui_e2e.py</code></td><td>v2 启动流上的 L0 TUI 命令</td></tr><tr><td>中文控制台 E2E</td><td><code>tools/wp10_chinese_e2e.py</code></td><td>CJK 层端到端</td></tr><tr><td>TUI 桌面应用 E2E</td><td><code>tools/wp10_tuiqa_apps_e2e.py</code></td><td>从 <code>ush&gt;</code> 起步的桌面五应用流程</td></tr><tr><td>原生桌面 E2E</td><td><code>tools/wp10_native_e2e.py</code></td><td>原生编辑器/文件管理器流程</td></tr><tr><td>L1 逐应用记录</td><td>从 ush 经 <code>run</code> 跑每个 <code>l1apps/</code> 程序</td><td>ush + 每个嵌入程序真实执行（2.1.0 新增；见 docs/dev/e2e-suites.md）</td></tr></tbody></table><h2 id="_5-tag-release" tabindex="-1">5. Tag + Release <a class="header-anchor" href="#_5-tag-release" aria-label="Permalink to &quot;5. Tag + Release&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git tag -a v&lt;版本&gt;            # 只打在 CI 绿的提交上</span></span>
<span class="line"><span>git push origin main --tags</span></span></code></pre></div><p>从 tag 建 GitHub Release，说明含：变更摘要、新接口、已知问题、 三个 SHA256。附三份资产。发布脚本（<code>tools/build_release.sh --deep</code>） 自动完成清单 + 说明 + 上传。</p><p><strong>发布门（2.1.0）：tag 必须指向 CI 绿的提交。绝不在红的提交上打 tag。</strong></p><h2 id="_6-网站-wiki" tabindex="-1">6. 网站 + wiki <a class="header-anchor" href="#_6-网站-wiki" aria-label="Permalink to &quot;6. 网站 + wiki&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools/update_website.sh    （版本/哈希/下载）</span></span>
<span class="line"><span>tools/sync_wiki.sh         （docs/ -&gt; GitHub Wiki）</span></span></code></pre></div><p>门：线上站点显示新版本、三个 SHA256 与 Release 一致、下载 HTTP 200 且哈希校验通过、站点 stats 块<strong>从 <code>docs/data/*.json</code> 再生成</strong> （绝不从旧块照搬——2.0.0 的站点就是那样带着陈旧的 130,011 行数 发出去的）。</p><h2 id="_7-私密镜像" tabindex="-1">7. 私密镜像 <a class="header-anchor" href="#_7-私密镜像" aria-label="Permalink to &quot;7. 私密镜像&quot;">​</a></h2><p>把三份资产 + 发布说明 + 镜像的网站文件拷进私密仓（<code>oc-os/</code> 树 + 仓级 audit 文档）；推送。门：两个仓的 <code>git ls-remote</code> 显示预期的 HEAD。</p><h2 id="_8-12-点检查" tabindex="-1">8. 12 点检查 <a class="header-anchor" href="#_8-12-点检查" aria-label="Permalink to &quot;8. 12 点检查&quot;">​</a></h2><ol><li>两仓远端 HEAD 与本地一致。</li><li>tag 在公开仓存在且指向 CI 绿的提交。</li><li>每个发布提交的作者身份。</li><li>gh-pages 已更新（线上站点服务新版本）。</li><li>update.json：version + build + package_sha256（双副本—— website/ 顶层与 website/public/——字节一致）。</li><li>三方资产哈希：本地 = Release API digest = 实际下载。</li><li>网站数字（命令/接口/行数）与 <code>docs/data/*.json</code> 一致（再生成， 不是照搬）。</li><li>第 4 步的门全绿（贴输出，申报 skip 数）。</li><li>token 卫生（只显示 last-4）。</li><li>全仓数字一致性：251 命令归属（99+133+19）/ 17 类 / 158 个 L1SVC 操作 / 54 syscall / 当前 stats.json 行数（每次发布重算； 绝不带陈旧数字）。</li><li>私密镜像完整。</li><li>CI 在发布提交（及被 tag 的提交）上绿。</li></ol><h2 id="_9-报告" tabindex="-1">9. 报告 <a class="header-anchor" href="#_9-报告" aria-label="Permalink to &quot;9. 报告&quot;">​</a></h2><p>交付报告引用：构建证据（本地 + CI）、全部门输出、推送输出（公开 + 私密）、Release URL、站点 URL、三个 SHA256、以及诚实偏差清单。</p>`,29)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
